import http from 'http';

const server = http.createServer((req, res) => {
  // 设置 CORS 头，防止跨域问题
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  if (req.method === 'OPTIONS') {
    res.statusCode = 204;
    res.end();
    return;
  }

  // 辅助函数：以 JSON 格式返回响应
  const sendJSON = (data, status = 200) => {
    res.writeHead(status, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(data));
  };

  const { url, method } = req;

  // 1. Mock 登录接口
  if (url === '/api/auth/login' && method === 'POST') {
    sendJSON({
      token: 'mock-jwt-token-xyz',
      user: { id: 1, username: 'admin', email: 'admin@example.com', role: 'ADMIN' }
    });
  }
  // 2. Mock 获取当前登录用户信息
  else if (url === '/api/users/me' && method === 'GET') {
    sendJSON({
      id: 1,
      username: 'admin',
      email: 'admin@example.com',
      avatarUrl: null,
      role: 'ADMIN'
    });
  }
  // 3. Mock 图片上传接口 (POST /api/upload)
  else if (url === '/api/upload' && method === 'POST') {
    // 消费请求流以防连接意外截断
    let body = [];
    req.on('data', chunk => body.push(chunk));
    req.on('end', () => {
      sendJSON({
        url: 'https://picsum.photos/id/1025/800/600' // 返回一张固定的测试宠物狗图片链接
      });
    });
  }
  // 4. Mock 版块/分类列表
  else if (url === '/api/categories' && method === 'GET') {
    sendJSON([
      { id: 1, name: '技术分享', description: '代码、架构与开发技术交流' },
      { id: 2, name: '生活闲聊', description: '分享日常，闲聊人生' }
    ]);
  }
  // 5. Mock 帖子列表 / 帖子详情
  else if (url.startsWith('/api/posts')) {
    const detailMatch = url.match(/^\/api\/posts\/(\d+)/);
    if (detailMatch && method === 'GET') {
      // 返回帖子详情
      sendJSON({
        id: parseInt(detailMatch[1], 10),
        title: '关于论坛图片上传功能的测试主题',
        content: '今天测试了发帖编辑器中的图片上传功能，上传后的图片渲染为：\n\n![测试可爱狗狗](https://picsum.photos/id/1025/400/300)\n\n这应该能正常显示为一张狗子的图片。如果显示出来了，说明 Markdown 解析渲染工作正常！',
        viewCount: 128,
        likeCount: 5,
        isLikedByCurrentUser: false,
        isBookmarkedByCurrentUser: false,
        categoryId: 1,
        categoryName: '技术分享',
        authorUsername: 'admin',
        authorAvatarUrl: null,
        createdAt: new Date(Date.now() - 3600000).toISOString(),
        updatedAt: null
      });
    } else if (method === 'POST') {
      // 创建新帖子
      let body = '';
      req.on('data', chunk => body += chunk);
      req.on('end', () => {
        const data = JSON.parse(body || '{}');
        sendJSON({
          id: 99,
          title: data.title || '新发表的帖子',
          content: data.content || '',
          viewCount: 0,
          likeCount: 0,
          authorUsername: 'admin',
          createdAt: new Date().toISOString()
        }, 201);
      });
    } else {
      // 帖子列表
      sendJSON({
        content: [
          {
            id: 1,
            title: '关于论坛图片上传功能的测试主题',
            categoryId: 1,
            categoryName: '技术分享',
            authorUsername: 'admin',
            viewCount: 128,
            createdAt: new Date(Date.now() - 3600000).toISOString()
          }
        ],
        totalElements: 1,
        totalPages: 1
      });
    }
  }
  // 6. Mock 评论列表 / 评论创建
  else if (url.startsWith('/api/comments')) {
    if (method === 'POST') {
      let body = '';
      req.on('data', chunk => body += chunk);
      req.on('end', () => {
        const data = JSON.parse(body || '{}');
        sendJSON({
          id: 100,
          content: data.content || '',
          authorUsername: 'admin',
          createdAt: new Date().toISOString(),
          replies: []
        }, 201);
      });
    } else {
      sendJSON([
        {
          id: 1,
          content: '非常棒的图片上传功能！我也试一下展示效果：\n\n![小黑狗](https://picsum.photos/id/237/200/150)',
          authorUsername: 'test_user',
          authorAvatarUrl: null,
          createdAt: new Date().toISOString(),
          replies: []
        }
      ]);
    }
  }
  // 7. 兜底
  else {
    sendJSON({ message: `Mock API: ${method} ${url} 暂未完全实现。` }, 404);
  }
});

server.listen(9000, () => {
  console.log('==================================================');
  console.log('Mock API server is running on http://localhost:9000');
  console.log('Vite 代理流量已自动转发至此处。');
  console.log('==================================================');
});

